#
# ADD 1+1 Firmware Payload
# Equivalent of the firmware generated by gen_hex.py
#
# This is loaded to SRAM at address 0x1000 by the UART bootloader,
# then the CPU jumps here to execute it.
#
# What it does:
#   1. Computes 1 + 1 = 2
#   2. Writes the result (2) to GPIO at 0x05000000
#   3. Sends ASCII '2' (0x32) via the old UART TX at 0x03000000
#   4. Returns to the bootloader (jalr x0, ra, 0)
#
# Register usage:
#   a0 (x10) - operand 1  (value = 1)
#   a1 (x11) - result      (value = 1+1 = 2)
#   a2 (x12) - base address temp
#   a3 (x13) - ASCII character temp
#

    .text
    .globl _payload_start

_payload_start:
    # =========================================================
    # 1. Compute 1 + 1
    # =========================================================
    addi  a0, x0, 1             # a0 = 1
    addi  a1, a0, 1             # a1 = a0 + 1 = 2

    # =========================================================
    # 2. Write result to GPIO (0x05000000) for LED display
    # =========================================================
    lui   a2, 0x05000           # a2 = 0x05000000 (GPIO base)
    sw    a1, 0(a2)             # GPIO = 2

    # =========================================================
    # 3. Send result as ASCII via UART TX (0x03000000)
    #    ASCII '0' = 0x30, so '2' = 0x30 + 2 = 0x32
    # =========================================================
    lui   a2, 0x03000           # a2 = 0x03000000 (UART base)
    addi  a3, a1, 0x30          # a3 = 2 + 0x30 = 0x32 = '2'
    sb    a3, 0(a2)             # write '2' to UART THR

    # =========================================================
    # 4. Return to bootloader
    # =========================================================
    jalr  x0, ra, 0             # ret (jump to address in ra)
